def adr(b):
 return re.match(r'\d+',b['address'])[0]
def groups_for(a):
 return [p['key'] for p in PLAN if a in p['addresses']]
def csvwrite(path,rows):
 with path.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def link(path,label=None):return f'[{label or path}]({BASE+path})'
def refs(ids):
 out=[]
 for rid in ids.split(';'):
  if not rid:continue
  i=IMAGE.get(rid)
  out.append(f"`{rid}`"+(f" — [{i['title']}]({i['catalog_url']}); {i.get('date')}; {i.get('rights')}." if i else ' — resolve in library before use.'))
 return '\n'.join('- '+x for x in out) or '- No dedicated controlling exterior selected; use mapped envelope and bounded local analogue.'

def default_spec(f):
 material=f['map_material_interpretation'];note=f['notes'];st=f['raw_story_basement_notation']
 if material=='none':return ('Non-building/phase conflict', 'Reserve lot surface, boundary and any separate rear structure; build a front house only where the 1904 reconciliation justifies it.', 'A 1911 empty polygon is not automatic proof of 1904 vacancy. '+note,'')
 family='Frame dwelling' if material=='frame' else ('Stone-front masonry' if 'stone' in material else 'Brick masonry')
 parts='Map-bound main body and attached wings; '+('painted clapboard, timber sash/eaves and porch' if material=='frame' else 'masonry corner bonds, recessed sash, lintels, foundation and high stoop')+'; independently declared roof, gutters, chimneys and rear elevation. '+note
 return family,parts,'Facade design, roof pitch, colours and unseen windows are reconstructed. Raw map notation '+st+' remains unexpanded until key interpretation; map plan controls plan shape, not a supposedly measured facade.',''

