  if fs:heads+=['**Map controls:** '+'; '.join(f"`{f['id']}` sheet {f['sheet']}: {f['raw_story_basement_notation'] or 'no storey notation'}, {f['map_material_interpretation']}, {f['notes']}" for f in fs),'']
  heads+=['**Decomposition for this property:** main shell and foundation → each roof volume → street openings/entry → side/rear openings → attached bays/porches → cornice/carving/metalwork → distinct service structures → grade/boundary/yard. These are separate configurable parts even when exported as a batched mesh. Service roof quantities are map polygon counts, not one generic shed per house.','',f"**Work ownership:** {ts(keys)}. Detached service work is in R20W/R20E/R28W/R28E/R35W/R35E/RP as geographically appropriate; Glessner already owns its own stable.", '', '**Evidence handles:** '+', '.join('`'+i+'`' for i in ids)+'. The library source IDs are not automatically valid `4d/data/sources` IDs; ingest only those actually used.',refs(evidence),'']
  reg.append(dict(record_id=b['id'],address=b['address'],scope=scope,library_status=b['status_1904'],disposition='excluded' if ex else 'retain_existing' if a=='1800' and scope=='core' else 'phase_or_identity_resolution' if a in ['1635','2126','1936'] and scope=='core' else 'build_or_reconstruct',family=fam,proposed_elements=parts,phase_and_uncertainty=trap,source_ids=b['source_ids'],image_ids=evidence,ticket_keys=','.join(keys),ticket_ids=ts(keys)))
