 (OUT/'FRONTAGE-REGISTER.md').write_text('\n'.join(fmd));csvwrite(OUT/'frontage-register.csv',fsrows)
 # Cover every viewer parcel independently of whether it currently hosts a named record.
 parcels=[]
 for p in SITE['parcels']:
  keys=sorted(set(k for a in p['addresses'] for k in groups_for(a)))
  if not keys:
   joined=' '.join(p['addresses'])
   if '1800' in joined:keys=['existing Glessner']
   elif any('1607' in a or '1609' in a or '1611' in a for a in p['addresses']):keys=['N08']
   elif any('1916' in a or '1930' in a for a in p['addresses']):keys=['C14A','C14B']
   else:keys=['D20' if any(a.startswith(('16','17')) for a in p['addresses']) else 'D28' if any(a.startswith(('18','19')) for a in p['addresses']) else 'D35']
  parcels.append(dict(parcel_id=p['id'],addresses=';'.join(p['addresses']),side=p['side'],frontage_ft=p.get('frontage_ft'),building_ids=';'.join(p.get('building_ids',[])),ticket_ids=ts(keys),limitation='Existing traced viewer parcel, not a surveyed 1904 footprint or unique-building count'))
